# Standalone verifier, no imports, no I/O, no filesystem, no network.
# Discipline: fail closed, exact integer arithmetic only, deterministic.
# The harness evaluates VERIFY and expects the Python object True.

BOUND = 59049  # 3^10

SEEDS = [[1, 2, 4], [1, 2, 3], [1, 2, 5], [1, 3, 4], [1, 4, 5]]

PATTERNS = [
    [1, 2, 1, 3, 1, 2, 3],
    [1, 2, 3, 1, 2, 1, 3],
    [1, 1, 3, 1, 1, 1, 2],
    [1, 2, 1, 1, 3, 1, 2],
    [2, 1, 1, 3, 1, 2, 1],
]

def greedy(seed, bound):
    # exact canonical greedy rule; returns (terms, gaps) with all terms < bound
    terms = list(seed)
    s = set()
    for i in range(len(terms)):
        for j in range(len(terms)):
            s.add(terms[i] + terms[j])
    gaps = []
    cur = terms[-1]
    while True:
        cand = cur + 1
        while cand in s:
            cand += 1
        if cand >= bound:
            break
        for x in terms:
            s.add(x + cand)
        gaps.append(cand - cur)
        terms.append(cand)
        cur = cand
    return terms, gaps

def matches(gaps, pat):
    period = len(pat)
    n = len(gaps)
    if n < 3 * period:
        return False
    # every complete period-aligned window must equal the pattern exactly
    nwin = n // period
    for w in range(nwin):
        if gaps[w * period:(w + 1) * period] != pat:
            return False
    # residual tail must be the matching prefix of the pattern
    rem = n - nwin * period
    if rem != 0 and gaps[nwin * period:] != pat[:rem]:
        return False
    return True

def verify():
    if BOUND != 3 ** 10:
        return False
    if len(SEEDS) != 5 or len(PATTERNS) != 5:
        return False
    for seed, pat in zip(SEEDS, PATTERNS):
        if len(seed) != 3:
            return False
        if not (seed[0] > 0 and seed[0] < seed[1] < seed[2]):
            return False
        if len(pat) != 7:
            return False
        terms, gaps = greedy(seed, BOUND)
        if len(terms) < 1 or terms[-1] >= BOUND:
            return False
        # warm-up: the sequence is periodic from the seed for these five cases,
        # but we require only that EVERY full window matches (strictest check)
        if not matches(gaps, pat):
            return False
    return True

VERIFY = verify()
